<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,AdSet,SyncRun,RawProviderPayload,CanonicalAudience,AudienceTargetingObservation,AudienceTargetingReference};
use App\Services\Advertising\Sync\{CanonicalAudienceRecorder,AdDataSyncEngine};
use App\Services\Advertising\OAuthManager;
use Mockery;
use App\Services\Advertising\Adapters\MetaAdsAdapter;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\Http;
use Tests\TestCase;
final class CanonicalAudienceTest extends TestCase {
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Synthetic','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Synthetic','currency'=>'USD']);$set=AdSet::create(['campaign_id'=>$c->id,'external_ad_set_id'=>'set','name'=>'Synthetic']);$run=SyncRun::create(['connected_ad_account_id'=>$a->id,'sync_type'=>'manual','status'=>'completed','started_at'=>now()]);$raw=RawProviderPayload::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','endpoint'=>'campaigns','payload'=>[]]);return[$u,$a,$set,$run,$raw];}
 public function test_roles_exact_retries_empty_and_unknown_fields_are_not_conflated():void{[$u,$a,$set,$run,$raw]=$this->fixture();$rec=new CanonicalAudienceRecorder;$d=['included'=>[['external_audience_id'=>'b','name'=>'B'],['external_audience_id'=>'a','name'=>'A']],'excluded'=>[['external_audience_id'=>'a','name'=>'A']]];$o=$rec->record($a,$set,$d,$run,$raw);$d['included']=array_reverse($d['included']);$this->assertSame($o->id,$rec->record($a,$set,$d,$run,$raw)->id);$this->assertSame(2,CanonicalAudience::where('connected_ad_account_id',$a->id)->count());$this->assertSame(3,AudienceTargetingReference::where('audience_targeting_observation_id',$o->id)->count());$this->assertTrue($o->included_observed);$this->assertTrue($o->excluded_observed);
 $run2=SyncRun::create(['connected_ad_account_id'=>$a->id,'sync_type'=>'manual','status'=>'failed','started_at'=>now()]);$empty=$rec->record($a,$set,['included'=>[]],$run2,$raw);$this->assertTrue($empty->included_observed);$this->assertFalse($empty->excluded_observed);$this->assertLessThan(2,abs($empty->fresh()->observed_at->timestamp-time()));}
 public function test_scope_conflicts_and_malformed_reference_lists_fail():void{[$u,$a,$set,$run,$raw]=$this->fixture();$rec=new CanonicalAudienceRecorder;$rec->record($a,$set,['included'=>[]],$run,$raw);foreach([['excluded'=>[]],['included'=>[['external_audience_id'=>'a'],['external_audience_id'=>'a']]],['included'=>[['external_audience_id'=>'a','members'=>[]]]],[],['included'=>null],['included'=>['invalid']],['included'=>[123]],['included'=>[false]]]as$d){try{$rec->record($a,$set,$d,$run,$raw);$this->fail('Invalid/conflicting data accepted');}catch(\RuntimeException){$this->assertTrue(true);}}[$ou,$oa,$foreign]=$this->fixture();try{$rec->record($a,$foreign,['included'=>[]],$run,$raw);$this->fail('Foreign scope accepted');}catch(\RuntimeException){$this->assertTrue(true);}}
 public function test_owned_private_inspection_retains_roles_and_detects_changed_labels():void{[$u,$a,$set,$run,$raw]=$this->fixture();$o=(new CanonicalAudienceRecorder)->record($a,$set,['included'=>[['external_audience_id'=>'a','name'=>'Synthetic']],'excluded'=>[]],$run,$raw);$base='/api/v1/ad-accounts/'.$a->id;$this->getJson($base.'/canonical-audiences')->assertUnauthorized();$this->actingAs($u,'sanctum')->getJson($base.'/canonical-audiences')->assertOk()->assertJsonPath('data.provider_verified',false)->assertJsonCount(1,'data.rows');$this->getJson($base.'/audience-targeting-observations')->assertJsonPath('data.rows.0.integrity_status','recorded_scope_consistent')->assertJsonPath('data.rows.0.references.0.role','included')->assertJsonPath('data.rows.0.excluded_observed',true);$run->update(['status'=>'failed']);$this->getJson($base.'/audience-targeting-observations')->assertJsonPath('data.rows.0.sync_status','failed');AudienceTargetingReference::where('audience_targeting_observation_id',$o->id)->update(['name'=>'Altered']);$this->getJson($base.'/audience-targeting-observations')->assertJsonPath('data.rows.0.integrity_status','mismatch')->assertJsonCount(0,'data.rows.0.references');$other=User::factory()->create();$this->actingAs($other,'sanctum')->getJson($base.'/canonical-audiences')->assertNotFound();$this->getJson($base.'/audience-targeting-observations')->assertNotFound();}
 public function test_meta_mapping_keeps_explicit_roles_empty_and_missing_distinct():void{[$u,$a]=$this->fixture();Http::preventStrayRequests();Http::fake(['graph.facebook.com/*/campaigns*'=>Http::response(['data'=>[['id'=>'c','name'=>'Synthetic','adsets'=>['data'=>[['id'=>'s1','targeting'=>['custom_audiences'=>[['id'=>'11','name'=>'Synthetic']],'excluded_custom_audiences'=>[]]],['id'=>'s2','targeting'=>[]]]]]]],200)]);$result=(new MetaAdsAdapter)->fetchCampaigns($a);$refs=$result['campaigns'][0]['ad_sets'];$this->assertSame('11',$refs[0]['canonical_audience_references']['included'][0]['external_audience_id']);$this->assertSame([],$refs[0]['canonical_audience_references']['excluded']);$this->assertNull($refs[1]['canonical_audience_references']);Http::fake(['graph.facebook.com/*/campaigns*'=>Http::response(['data'=>[['id'=>'c','name'=>'Synthetic','adsets'=>['data'=>[['id'=>'s1','targeting'=>['custom_audiences'=>[['id'=>'11','name'=>'Synthetic']],'excluded_custom_audiences'=>[]]],['id'=>'s2','targeting'=>[]]]]]]],200),'graph.facebook.com/*/insights*'=>Http::response(['data'=>[]],200)]);$manager=Mockery::mock(OAuthManager::class);$manager->shouldReceive('getAdapter')->with('meta')->andReturn(new MetaAdsAdapter);$run=(new AdDataSyncEngine($manager))->syncAccount($a,'manual','2026-11-01','2026-11-01');$this->assertSame('completed',$run->status);$this->assertSame(1,AudienceTargetingObservation::where('sync_run_id',$run->id)->count());}
}
